import { useState } from "react";

const LAU_GREEN = "#1a6b3c";
const LAU_GREEN_DARK = "#145430";
const LAU_GREEN_LIGHT = "#f0f7f3";
const LAU_GREEN_BORDER = "#d4e8db";

const styles = {
  page: {
    minHeight: "100vh",
    background: LAU_GREEN_LIGHT,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    padding: "2rem 1rem",
    fontFamily: "Segoe UI, sans-serif",
  },
  wrapper: {
    width: "100%",
    maxWidth: "420px",
  },
  header: {
    textAlign: "center",
    marginBottom: "24px",
  },
  logoRow: {
    display: "inline-flex",
    alignItems: "center",
    gap: "10px",
    marginBottom: "6px",
  },
  logoBox: {
    width: "36px",
    height: "36px",
    background: LAU_GREEN,
    borderRadius: "8px",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  logoText: {
    fontSize: "22px",
    fontWeight: "500",
    color: LAU_GREEN,
  },
  subtitle: {
    fontSize: "13px",
    color: "#666",
    margin: 0,
  },
  card: {
    background: "#fff",
    borderRadius: "14px",
    border: `0.5px solid ${LAU_GREEN_BORDER}`,
    overflow: "hidden",
  },
  tabRow: {
    display: "flex",
    borderBottom: "0.5px solid #eee",
  },
  tabBtn: (active) => ({
    background: "none",
    border: "none",
    borderBottom: active ? `2px solid ${LAU_GREEN}` : "2px solid transparent",
    padding: "10px 32px",
    fontSize: "15px",
    fontWeight: "500",
    cursor: "pointer",
    color: active ? LAU_GREEN : "#888",
    transition: "all 0.2s",
  }),
  body: {
    padding: "24px",
  },
  hint: {
    fontSize: "13px",
    color: "#666",
    margin: "0 0 20px",
  },
  label: {
    fontSize: "13px",
    color: "#555",
    display: "block",
    marginBottom: "5px",
  },
  input: {
    width: "100%",
    boxSizing: "border-box",
    padding: "10px 14px",
    border: "0.5px solid #ccc",
    borderRadius: "8px",
    fontSize: "14px",
    marginBottom: "14px",
    background: "#fff",
    color: "#222",
    outline: "none",
    fontFamily: "inherit",
  },
  forgotRow: {
    textAlign: "right",
    marginTop: "-8px",
    marginBottom: "16px",
  },
  forgotLink: {
    fontSize: "13px",
    color: LAU_GREEN,
    textDecoration: "none",
  },
  submitBtn: {
    width: "100%",
    padding: "11px",
    background: LAU_GREEN,
    color: "#fff",
    border: "none",
    borderRadius: "8px",
    fontSize: "15px",
    fontWeight: "500",
    cursor: "pointer",
    fontFamily: "inherit",
  },
  divider: {
    display: "flex",
    alignItems: "center",
    gap: "10px",
    margin: "16px 0",
    color: "#aaa",
    fontSize: "13px",
  },
